96	- [ ] **Step 3: Implement**
97	
98	```ts
99	export type DayLog = { worn_on: string; outfitId: string; imageUrl?: string };
100	export type Cell = {
101	  key: string;
102	  day: number | null;
103	  inMonth: boolean;
104	  isToday: boolean;
105	  log?: DayLog;
106	};
107	
108	/** Monday-first, matching the design's weekday header. */
109	function mondayIndex(jsDay: number): number {
110	  return (jsDay + 6) % 7;
111	}
112	
113	function iso(year: number, month: number, day: number): string {
114	  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
115	}
116	
117	/**
118	 * The month grid. `month` is 1-12, not JS's 0-11 — the off-by-one there is a
119	 * classic and this boundary is the place to absorb it.
120	 *
121	 * `today` is passed in rather than read from the clock so the whole thing stays
122	 * pure and testable, and so the caller can supply the user's LOCAL date.
123	 */
124	export function buildMonth(year: number, month: number, today: string, logs: DayLog[]): Cell[] {
125	  const byDate = new Map(logs.map((l) => [l.worn_on, l]));
126	  const first = new Date(Date.UTC(year, month - 1, 1));
127	  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
128	  const lead = mondayIndex(first.getUTCDay());
129	
130	  const cells: Cell[] = [];
131	  for (let i = 0; i < lead; i++) {
132	    cells.push({ key: `lead-${i}`, day: null, inMonth: false, isToday: false });
133	  }
134	  for (let d = 1; d <= daysInMonth; d++) {
135	    const date = iso(year, month, d);
136	    cells.push({
137	      key: date,
138	      day: d,
139	      inMonth: true,
140	      isToday: date === today,
141	      log: byDate.get(date),
142	    });
143	  }
144	  while (cells.length % 7 !== 0) {
145	    cells.push({ key: `trail-${cells.length}`, day: null, inMonth: false, isToday: false });
146	  }
147	  return cells;
148	}
149	```
