200	
201	```ts
202	function shiftDay(date: string, delta: number): string {
203	  const d = new Date(`${date}T00:00:00Z`);
204	  d.setUTCDate(d.getUTCDate() + delta);
205	  return d.toISOString().slice(0, 10);
206	}
207	
208	/**
209	 * Consecutive days with at least one wear, counting back from today.
210	 *
211	 * A streak ending YESTERDAY still counts. Anchoring strictly on today would
212	 * show every user a zero every morning until they dressed, which reads as
213	 * "you lost your streak" rather than "the day is young".
214	 *
215	 * Dates are UTC-shifted only for arithmetic; the values themselves are the
216	 * user's local date keys, so no timezone conversion happens here.
217	 */
218	export function currentStreak(dates: string[], today: string): number {
219	  const set = new Set(dates);
220	  let cursor = set.has(today) ? today : shiftDay(today, -1);
221	  if (!set.has(cursor)) return 0;
222	
223	  let n = 0;
224	  while (set.has(cursor)) {
225	    n++;
226	    cursor = shiftDay(cursor, -1);
227	  }
228	  return n;
229	}
230	```
