153	import { personalBand } from "@/lib/generator/rules";
154	import type { Weather } from "@/lib/generator/rules";
155	import type { UiOccasion } from "@/lib/generator/types";
156	
157	/**
158	 * The archetypal pieces we know how to recommend. Deliberately small and
159	 * neutral: the claim is "this unlocks N outfits", and a wilder candidate would
160	 * inflate N while being something the user would never buy.
161	 */
162	export type GapCandidate = { label: string; category: string; colors: string[]; formality: number };
163	
164	export const GAP_CANDIDATES: GapCandidate[] = [
165	  { label: "A camel overcoat", category: "Outerwear", colors: ["camel"], formality: 4 },
166	  { label: "Grey wool trousers", category: "Bottoms", colors: ["grey"], formality: 4 },
167	  { label: "A navy knit", category: "Tops", colors: ["navy"], formality: 3 },
168	  { label: "Brown leather loafers", category: "Shoes", colors: ["brown"], formality: 4 },
169	  { label: "A white oxford shirt", category: "Tops", colors: ["white"], formality: 4 },
170	  { label: "Dark denim", category: "Bottoms", colors: ["denim"], formality: 2 },
171	  { label: "Clean white sneakers", category: "Shoes", colors: ["white"], formality: 2 },
172	];
173	
174	function countCombos(closet: CandidateItem[], occasions: UiOccasion[], weather: Weather): number {
175	  return occasions.reduce((total, o) => {
176	    const args = {
177	      band: personalBand(o, null),
178	      weather,
179	      season: undefined as unknown as string,
180	      excludeItemIds: [],
181	      maxAccessories: 0,
182	    };
183	    return total + buildCandidates(closet, args).length;
184	  }, 0);
185	}
186	
187	/**
188	 * Which single hypothetical piece would unlock the most outfits.
189	 *
190	 * The number is produced by the SAME code that builds real outfits, so "unlocks
191	 * 14 new outfits" means exactly that — not a heuristic that resembles it.
192	 */
193	export function biggestGap(
194	  closet: CandidateItem[],
195	  occasions: UiOccasion[],
196	  weather: Weather,
197	): { candidate: GapCandidate; unlocks: number } | null {
198	  if (!closet.length) return null;
199	
200	  const before = countCombos(closet, occasions, weather);
201	  let best: { candidate: GapCandidate; unlocks: number } | null = null;
202	
203	  for (const c of GAP_CANDIDATES) {
204	    const hypothetical: CandidateItem = {
205	      id: "__hypothetical__",
206	      category: c.category,
207	      colors: c.colors,
208	      formality: c.formality,
209	      seasons: [],
210	      material: null,
211	      pattern: "solid",
212	      texture: null,
213	    };
214	    const unlocks = countCombos([...closet, hypothetical], occasions, weather) - before;
215	    if (unlocks > 0 && (!best || unlocks > best.unlocks)) best = { candidate: c, unlocks };
216	  }
217	  return best;
218	}
219	```
