105	- [ ] **Step 3: Implement**
106	
107	```ts
108	const GBP = new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" });
109	
110	function daysBetween(from: string, to: string): number {
111	  const a = Date.UTC(+from.slice(0, 4), +from.slice(5, 7) - 1, +from.slice(8, 10));
112	  const b = Date.UTC(+to.slice(0, 4), +to.slice(5, 7) - 1, +to.slice(8, 10));
113	  return Math.round((b - a) / 86_400_000);
114	}
115	
116	/**
117	 * The three tiles at the top of item detail.
118	 *
119	 * Cost-per-wear is null rather than 0 or "—" when there is no price or no
120	 * wears: dividing by zero wears would print £Infinity, and showing £0.00 for an
121	 * unpriced item states something false. The UI hides the tile instead.
122	 */
123	export function itemWearStats(
124	  logs: { worn_on: string }[],
125	  price: number | null,
126	  today: string,
127	): { wears: number; costPerWear: string | null; lastWorn: string } {
128	  const wears = logs.length;
129	  const costPerWear = price != null && wears > 0 ? GBP.format(price / wears) : null;
130	
131	  if (!wears) return { wears, costPerWear, lastWorn: "Never" };
132	
133	  const latest = logs.reduce((a, b) => (a.worn_on > b.worn_on ? a : b)).worn_on;
134	  const d = daysBetween(latest, today);
135	  const lastWorn = d <= 0 ? "Today" : d === 1 ? "Yesterday" : `${d} days ago`;
136	  return { wears, costPerWear, lastWorn };
137	}
138	```
