192	- [ ] **Step 3: Implement**
193	
194	```ts
195	import { colorHarmonyScore } from "@/lib/generator/color";
196	import { formalityCoherence } from "@/lib/generator/score";
197	
198	type Piece = { id: string; category: string; colors: string[]; formality: number | null };
199	
200	/**
201	 * The "Goes with" row (Fitcheck.dc.html:641-649).
202	 *
203	 * Reuses the generator's own colour-harmony and formality-coherence scoring
204	 * rather than inventing a second opinion — if these two disagreed, the row
205	 * would recommend pieces the stylist would never pair, which is worse than an
206	 * empty row. Deterministic and free: no AI call on this screen.
207	 */
208	export function goesWith(subject: Piece, closet: Piece[], n = 5): string[] {
209	  return closet
210	    .filter(
211	      (i) =>
212	        i.id !== subject.id &&
213	        i.category !== subject.category &&
214	        i.category !== "Fragrance",
215	    )
216	    .map((i) => ({
217	      id: i.id,
218	      score:
219	        0.6 * colorHarmonyScore([...subject.colors, ...i.colors]) +
220	        0.4 * formalityCoherence([subject.formality ?? 3, i.formality ?? 3]),
221	    }))
222	    .sort((a, b) => b.score - a.score)
223	    .slice(0, n)
224	    .map((x) => x.id);
225	}
226	```
