117	
118	```ts
119	/**
120	 * Season is a PREFERENCE, not an eligibility gate.
121	 *
122	 * A hard season filter ran against every REQUIRED slot, so one narrowly-tagged
123	 * category could zero the entire result: trousers tagged {Spring,Summer,Autumn}
124	 * meant no eligible bottoms in December, and every occasion returned "add a few
125	 * more pieces" from a perfectly wearable closet. Outerwear and the Refine colour
126	 * lean both moved to the soft-preference model for exactly this reason; season
127	 * now follows them — it orders candidates and weights the score, and can never
128	 * eliminate one.
129	 *
130	 * The MEASURED signal still filters hard (`weatherRules`: rain excludes suede,
131	 * cold adds a layer). That is a real reading of the day. A season tag is a
132	 * coarse label derived from the calendar month, which is a much blunter
133	 * instrument and does not deserve veto power.
134	 */
135	
136	/**
137	 * Does this item suit the season?
138	 *
139	 * Case-insensitive on purpose: the DB and the AI tagger store Title case
140	 * ("Winter", `lib/ai/tagging-schema.ts`) while the generator's test fixtures use
141	 * lower case. An untagged item counts as in-season — absence of tags is absence
142	 * of an opinion, not a reason to rank it last.
143	 */
144	export function inSeason(seasons: string[] | undefined, season: string | undefined): boolean {
145	  if (!season) return true;
146	  if (!seasons || seasons.length === 0) return true;
147	  const s = season.toLowerCase();
148	  return seasons.some((x) => x.toLowerCase() === s);
149	}
150	
151	/** The fraction of a combo's pieces that suit the season. 1 = all of them. */
152	export function seasonFit(items: { seasons?: string[] }[], season: string | undefined): number {
153	  if (!items.length) return 1;
154	  return items.filter((i) => inSeason(i.seasons, season)).length / items.length;
155	}
156	
157	/** Title case to match the DB tag vocabulary. */
158	export function currentSeason(d: Date): string {
159	  const m = d.getMonth();
160	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
161	}
162	```
