251	```ts
252	import { colorHarmonyScore, leanScore } from "./color";
253	import { seasonFit } from "./season";
254	
255	export type ScoreItem = {
256	  category: string;
257	  colors: string[];
258	  formality: number | null;
259	  style_tags?: string[];
260	  seasons?: string[];
261	};
262	export type Ctx = {
263	  aesthetic: string[];
264	  band: [number, number];
265	  /** Refine "Lean into" colour families. Empty = no preference. */
266	  lean?: string[];
267	  /** The current season ("Winter"). Absent = no season preference at all. */
268	  season?: string;
269	};
270	
271	/**
272	 * How much of the score the colour lean is allowed to claim when one is asked
273	 * for. High enough to reorder the top 20 decisively, low enough that a combo
274	 * missing the colour still beats an incoherent one that has it — the lean is a
275	 * preference, never an eliminator.
276	 */
277	const LEAN_WEIGHT = 0.3;
278	
279	/**
280	 * The same bargain for season. Slightly lower than the lean because a lean is an
281	 * explicit request the user just made, while season is inferred from the month.
282	 * Both together cap at 0.5, so coherence and colour harmony always keep half the
283	 * score — an off-season combo that actually works still beats an in-season mess.
284	 */
285	const SEASON_WEIGHT = 0.2;
286	
287	/** 1.0 = identical formality; falls off with spread. */
288	export function formalityCoherence(formalities: number[]): number {
289	  const f = formalities.filter((x) => typeof x === "number");
290	  if (f.length < 2) return 1;
291	  const spread = Math.max(...f) - Math.min(...f);
292	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
293	}
294	
295	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
296	  const colors = items.flatMap((i) => i.colors);
297	  const harmony = colorHarmonyScore(colors);
298	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
299	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
300	  const dna = items.length ? dnaHits / items.length : 0;
301	  const base = 0.45 * harmony + 0.35 * coherence + 0.2 * dna;
302	
303	  // Each preference claims its weight only when it applies, so with neither one
304	  // set the score is byte-identical to what it was before either landed.
305	  const wl = ctx.lean?.length ? LEAN_WEIGHT : 0;
306	  const ws = ctx.season ? SEASON_WEIGHT : 0;
307	  return Math.min(
308	    1,
309	    base * (1 - wl - ws) + wl * leanScore(colors, ctx.lean ?? []) + ws * seasonFit(items, ctx.season),
310	  );
311	}
312	```
