/** How many model-spending generations this user has made on their local today. */
export async function generationsUsedToday(userId: string, today: string): Promise<number> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("outfits")
    .select("occasion")
    .eq("generated_on", today);

  // COUNT DISTINCT OCCASIONS, NOT ROWS. saveDailyLooks inserts one outfits row
  // per LOOK (lib/outfits/daily.ts) — three per generation — so counting rows
  // would report 3 after a single drop and block a free user on their second
  // generation of the day instead of their fourth.
  return new Set((data ?? []).map((r) => r.occasion)).size;
}
```

> `generationsUsedToday` derives the count from stored outfit rows. That is a **proxy**, not a ledger,
> and it is wrong in one known direction: a regenerate REPLACES the day's rows for an occasion rather
> than adding a group, so repeat generations of the same occasion are not counted. Task 4 records why
> that is acceptable for now and what would replace it.

